python3 -I -c "
import json,glob,re,os
seen={}
qmap=dict(l.strip().split('|',1) for l in open('$D/qmap.txt'))
for f in sorted(glob.glob('$D/epmc/q*.json')):
    n=os.path.basename(f)[1:-5]
    try: d=json.load(open(f))
    except: continue
    for r in d.get('resultList',{}).get('result',[]):
        k=r.get('id')
        if k in seen: seen[k]['q'].add(n); continue
        seen[k]={'pmid':r.get('pmid','-'),'pmc':r.get('pmcid','-'),'y':r.get('pubYear'),'j':r.get('journalTitle','')[:28],'t':re.sub('<[^>]+>','',r.get('title','')),'doi':r.get('doi','-'),'q':{n}}
print('total unique records screened:',len(seen))
import pickle; pickle.dump(seen,open('$D/seen.pkl','wb'))
# print only likely-relevant
kw=re.compile(r'ovalbumin|ovotransferrin|conalbumin|ovomucoid|ovomucin|avidin|lysozyme|cystatin|leghemoglobin|leghaemoglobin|hemoglobin|haemoglobin|myoglobin|neuroglobin|globin|heme|haem|egg', re.I)
rel=[(v['y'],k,v) for k,v in seen.items() if kw.search(v['t'])]
rel.sort(reverse=True)
print('keyword-relevant:',len(rel))
for y,k,v in rel: print(v['pmid'],v['pmc'],y,v['j'],'|',v['t'][:135])
"

